<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mport extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY . "mportmodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mportmodel->fnGetPortInfo('', '', '', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $ArrData['ArrCountryList'] = unserialize(ARRCOUNTRYLIST);        $this->load->view(CNFCOMPANY . 'addeditport', $ArrData);    }    public function updatePortInfo() {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrResult = array();        $VarPortName = xssclean($this->input->post('pn'));        $VarPortCity = xssclean($this->input->post('cty'));        $VarPortCountry = xssclean($this->input->post('pcntry'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarPortName <> '') {            $ArrUpdateData = array('id' => $VarId, 'portname' => $VarPortName, 'portcity' => $VarPortCity,                'portcountry' => $VarPortCountry, 'status' => $VarStatus, 'updatedby' => $this->userid,                'companyid' => $this->companyid, 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mportmodel->savePortInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function manageport() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarPortName = trim(xssclean($this->input->post('pn')));        $VarPortCity = trim(xssclean($this->input->post('cty')));        $VarPortCountry = xssclean($this->input->post('pcntry'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('portname', 'portcity', 'countryname', 'pn.status', 'contactname', 'pn.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mport/manageport/';            $config['total_rows'] = $this->mportmodel->fnCountPort($VarPortName, $VarPortCity, $VarPortCountry, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "pn.dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrPortList = $this->mportmodel->fnListPort($VarPortName, $VarPortCity, $VarPortCountry, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Port');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            $ArrCountryList = unserialize(ARRCOUNTRYLIST);            foreach ($ArrPortList as $ObjPort) {                $ArrFnlList[$i]['id'] = $ObjPort->id;                $ArrFnlList[$i]['pn'] = $ObjPort->portname;                $ArrFnlList[$i]['cty'] = $ObjPort->portcity;                $ArrFnlList[$i]['pcntry'] = $ObjPort->countryname;                $ArrFnlList[$i]['ub'] = $ObjPort->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjPort->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i A', strtotime($ObjPort->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'manageport');        }    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actDeact'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mportmodel->fnChangeComStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }}